INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1537188-ae422', 'stk-alialrajjal', 'AE 422', 'info', '{"desc": "جودة المقرر بشكل عام\nالمقرر عن محركات الطائرات وهو جدا مهم وممتع في نفس الوقت\nالمواضيع التي يغطيها المقرر\nالمقرر يتكلم في البدايه عن الغاز وكيف يتصرف اذا انضغط بتستخدم المعادلات الي في الثرمو والقاز داينامكس وحتى الايرو\nبعدها بتدخل في الشوك ويفز بعدها يبدا الكلام عن محرك الطائره وكيف يشتغل وال Parametric cycle analysis وتختم المقرر بمحركات الصواريخ\nالكتاب المستخدم للمقرر\nElements of Propulsion: Gas Turbines and Rockets” by Jack D. Mattingly and Hans von Ohain, AIAA Pub. Ltd., Inc. 1801. 2nd Edition, (2016).\n\nاخذت المقرر في ٢٣١", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-422-flight-propulsion-i/120808/2", "user": "AliAlrajjal", "ts": 1704225259000, "tid": 120808, "pn": 2}}', 1704225259000, 1794826831, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1307276-ae422', 'stk-ibra1991', 'AE 422', 'info', '{"desc": "يا أخوان انا ميكانيكال و ناوي انزل مادة كالكتيف كورس ae422 Flight Propulsion I الفصل الجاي 132\nاتمنى اعرف مستوى صعوبتها وطريقة الهوموركات يعني هل تسبب ضغط على الطالب وافضل طريقة\nللمذاكرة يعني هل اكتفي بالسلايدات او بالكتاب بس. وهل فيها مفاهيم خاصة للإيروسبيس فيها\nصعوبة\nطبعا الدكتور NAVEED AHMED SYED هل هو جيد او لا انا قريت تقييم له بس ما كان فيه تفصيل بقسم تقييم هئية اعضاء التدريس.\nاخيرا ابغى نصيحتكم بمواد من ال ae انزلها كإلكتيف تكون سهلة\n\nشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae422-flight-propulsion/154077/1", "user": "ibra1991", "ts": 1387481381000, "tid": 154077, "pn": 1}}', 1387481381000, 1794826831, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317356-ae422', 'stk-yasser_29', 'AE 422', 'info', '{"desc": "هلا والله بالميكانيكال\n\nالكورس مستواه متوسط والماتيريال جمميل وممتع\nالكورس يتكلم عن محركات الطيارات بشكل عام بعدين يفصل في الكلام عن كل جزء من المحرك\n\nاول شي بيكون مراجعه بسيطه لاساسيات الثيرمو داينمكس وال shock waves …\nفهمها سهل بس في الاختبار تحتاج تركيز لان تصحيح الدكتور دقيق جدا\n\nماتيريال ميجر تو بتتكلم بتفصيل عن اداء كل جزء من المحرك , Inlet nozzle, Compressor, Combustion chamber, Turbine, Exhaust nozzle\n\nبعدها بيتكلم الكورس عن محركات الصواريخ بشكل مبسط ووش تحتاج عشان توصل الصاروخ لمداره وشوية heat transfer … بس تحتاج المعادلات الاساسيه\n\n--------------------------------\n\nعندك بروجيكت عباره عن بحث عن محرك طياره و 4 هومووركات مستواها متوسط الى سهل لا تفوتها\n\nالمذاكره من سلايدات الدكتور وفي المسائل الحسابيه يعطيك مانوال لحلها وامثله محلوله ويحلها في الكلاس ويعطيك ارقام صفحات من الكتاب اذا تبي زيادة فهم\n\nالكورس ما فيه افرج بس مهوب ستاندرد … ما عندي درجة الفاينل والبروجيكت عشان افصل لك بس مياجري تحت 80 وغياباتي قليله وطلعني ب B+\n\nأهم شي تفهم طريقة اسئلة الدكتور لانه يجيك تعداد ولا دريفايشن ما تكون متوقعه\nبرفع المياجر محلوله من الدكتور في ال kfupm resources\n\nالدكتور طيب حبيب ويتقبل اي سؤال واذا ما يعرف يقولك براجع المعلومه واعلمك\nالكورس ممتع خصوصا اذا انت مهتم بالطيران بتستفيد منه كثير\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae422-flight-propulsion/154077/3", "user": "yasser_29", "ts": 1389190882000, "tid": 154077, "pn": 3}}', 1389190882000, 1794826831, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1321255-ae422', 'stk-user3197', 'AE 422', 'info', '{"desc": "الكورس حلو وممتع وتحس انك بتطير وانت تدرسه ^^ ,\n\nوانا صراحه كنت خايف من نفيد لاني اخذت عنده كورس قبل وخفس بي بالقريد لكن في هالكورس اكتشفت انه يعطيك ع درجاتك , وصراحه حسيت انه منصف, \" b+ \"\n\nالكورس مايعتمد ع مبادىء الايروسبيس , غير الصواريخ شوي , لكن بيبدا معك من الصفر في كل شيء , وهذا من الايجابيات والسلبيات للدكتور .\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae422-flight-propulsion/154077/4", "user": "user3197", "ts": 1390357780000, "tid": 154077, "pn": 4}}', 1390357780000, 1794826831, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
